function PALLC(){ return POLICY.concat(polUser); }

const nSel=()=>Object.keys(sel.desc).length;

function renderPolicy(){
  const list=document.getElementById('polList'); if(!list) return;
  const cat=(document.getElementById('polCat')||{}).value||'all';
  const only=(document.getElementById('polOnly')||{}).value||'all';
  const all=PALLC();
  const arr=all.filter(p=>(cat==='all'||p.c===cat)&&(only==='all'||(only==='hit')===(p.m.length>0)));
  if(!arr.length){
    list.innerHTML='<div class="empty" style="padding:34px;">没有符合条件的路径</div>';
  }else{
    let h='', last='';
    arr.forEach(p=>{
      const i=all.indexOf(p);
      if(p.c!==last){ h+='<div class="pgh">'+p.c+'</div>'; last=p.c; }
      h+='<div class="pitem'+(i===polSel?' sel':'')+'" onclick="pickPolicy('+i+')">'+
         '<span class="pn">'+p.n+'</span>'+
         '<span class="pa">'+(p.a==='地方补充'?'地方':(p.a||'—'))+'</span>'+
         (p.m.length?('<span class="pm">'+p.m.length+'</span>'):'<span class="pm no">0</span>')+
         (polEvid(p)?'<span class="pe" title="数据集里有工具级记录">证</span>':'')+
         '</div>';
    });
    list.innerHTML=h;
  }
  const hit=all.filter(p=>p.m.length>0).length;
  const covered={};
  all.forEach(p=>p.m.forEach(x=>{ covered[x[0]]=1; }));
  const evN=all.filter(p=>polEvid(p)).length;
  const qN=all.filter(p=>{ const e=polEvid(p); return e&&e.q&&e.q.length; }).length;
  document.getElementById('polStat').innerHTML=
    '<span class="kv"><span>政策路径</span><span>'+all.length+' 条</span></span>'+
    '<span class="kv"><span>有对应描述符</span><span style="color:var(--ok)">'+hit+' 条</span></span>'+
    '<span class="kv"><span>无对应</span><span style="color:var(--tx2)">'+(all.length-hit)+' 条</span></span>'+
    '<span class="kv"><span>覆盖描述符</span><span>'+Object.keys(covered).length+' / '+allDescs().length+' 个</span></span>'+
    '<span class="kv"><span>有工具级记录</span><span>'+evN+' 条</span></span>'+
    '<span class="kv"><span>含定量口径</span><span>'+qN+' 条</span></span>'+
    '';
  polSidePanel();
}

function pickPolicy(i){ polSel=i; renderPolicy(); }

function polEvid(p){
  return (typeof POLICY_EVID!=='undefined' && POLICY_EVID[p.n]) ? POLICY_EVID[p.n] : null;
}

function polEvidBlock(p){
  const e=polEvid(p);
  if(!e) return '<div class="slabel">政策依据</div>'
    +'<div class="evbox none">该路径在数据集中<b>尚无工具级记录</b>——映射只能靠模型侧推断，'
    +'置信度按「中/低」处理。</div>';
  const mine=p.m.map(x=>x[0]);
  const theirs=e.d||[];
  const both=mine.filter(x=>theirs.indexOf(x)>=0);
  const onlyMine=mine.filter(x=>theirs.indexOf(x)<0);
  const onlyTheirs=theirs.filter(x=>mine.indexOf(x)<0);
  let h='<div class="slabel">政策依据（数据集 · 工具总览）</div><div class="evbox">';
  h+='<div class="evn">工具级记录 <b>'+e.n+'</b> 项'
    +(e.p&&e.p.length?'　·　涉及 '+e.p.join(' / '):'')+'</div>';
  if(e.f&&e.f.length) h+='<div class="evf">'+e.f.map(x=>'《'+x+'》').join('')+'</div>';
  if(e.q&&e.q.length) h+='<div class="evq">“'+e.q[0]+'”</div>';
  if(theirs.length){
    h+='<div class="evd">数据侧已实证：'+theirs.join('、')+'</div>';
    h+='<div class="evc">与模型侧比对：一致 <b>'+both.length+'</b>'
      +(onlyMine.length?'　·　模型侧另有 <b>'+onlyMine.length+'</b> 个':'' )
      +(onlyTheirs.length?'　·　数据侧另有 <b>'+onlyTheirs.length+'</b> 个':'')+'</div>';
    if(onlyTheirs.length) h+='<div class="evx">数据侧另有：'+onlyTheirs.join('、')
      +'　<span class="dim">（可能是绕一层的映射，也可能是口径差异，需人工核对）</span></div>';
    if(onlyMine.length) h+='<div class="evx">模型侧另有：'+onlyMine.join('、')
      +'　<span class="dim">（数据侧尚未建立该映射）</span></div>';
  }else{
    h+='<div class="evd dim">数据侧尚未为该路径建立描述符映射（409 条工具中仅 33 条已填）。</div>';
  }
  h+='<div class="dim" style="font-size:11px;margin-top:7px;line-height:1.7;">'
    +'文件名与口径来自数据集，能证明「这条政策存在」，<b>不能单独证明映射关系成立</b>——'
    +'映射仍需按「模型要什么 input」倒推判断。</div>';
  h+='</div>';
  return h;
}

function polSidePanel(){
  const el=document.getElementById('polSide'); if(!el) return;
  const all=PALLC();
  if(polSel==null||!all[polSel]){
    const cov={};
    all.forEach(p=>p.m.forEach(x=>{ cov[x[0]]=(cov[x[0]]||0)+1; }));
    el.innerHTML='<div class="shead">政策库对描述符的覆盖</div>'+
      allDescs().map(d=>{
        const c=cov[d.n]||0;
        return '<div class="covrow"><span class="cvd">'+d.n+'</span>'+
          '<span class="cvc'+(c?'':' zero')+'">'+(c?c+' 条路径':'无政策覆盖')+'</span></div>';
      }).join('')+
      '<div class="dim" style="font-size:13px;margin-top:11px;line-height:1.7;">'
      +'「经济增长速度」与「人口空间分布与收缩态势」零覆盖是正常的——'
      +'它们是外生的社会经济假设，不由政策工具驱动。</div>';
    return;
  }
  const p=all[polSel];
  el.innerHTML=
   '<div class="shead">'+(p.a==='地方补充'||p.a==='自定义'?'京津冀地方补充':'CCPID 国家库')+'</div>'+
   '<div class="pname">'+p.n+'</div>'+
   '<div class="pmeta">'+p.c+' · '+p.g+(p.s?' · '+p.s:'')+(p.t?'　工具 '+p.t+' 项':'')+'</div>'+
   polEvidBlock(p)+
   '<div class="slabel">对应到的描述符</div>'+
   (p.m.length? p.m.map(x=>{
     const v=POLICY_VERIF[p.n+'|'+x[0]];
     const up=!!(v&&v.st==='升高');
     const conf=up?(x[1]+'→高'):x[1];
     return '<div class="maprow"><div class="mr1"><b>'+x[0]+'</b>'+
     '<span class="conf '+(x[1]==='高'?'ok':(x[1]==='中'?'wn':'rd'))+(up?' up':'')+'">'+conf+'</span></div>'+
     '<div class="mr2">'+x[2]+'</div>'+
     (v?verifBlock(v):'')+'</div>';
   }).join('')
   : '<div class="dim" style="font-size:13px;line-height:1.7;">这条路径与本模型的描述符没有直接对应。'
     +'原因多为：控的不是 CO₂（如消耗臭氧层物质、含氟气体、塑料），或属于无定量落点的制度安排'
     +'（如信息披露、能力建设、宣传教育）。</div>');
}

function verifBlock(v){
  const up=v.st==='升高';
  return '<div class="vfbox">'
    +'<span class="vftag '+(up?'up':'keep')+'">'+(up?'补证成立 · 置信度升高':'已补证 · 维持原判')+'</span>'
    +'<div class="vff">《'+v.f+'》（'+v.no+'，'+v.d+'）</div>'
    +'<div class="vfq">“'+v.q+'”</div>'
    +'<a class="vfl" href="'+v.u+'" target="_blank" rel="noopener">查看政策原文 ↗</a>'
    +'</div>';
}

function applyPolicy(){
  if(nSel()===0){ toast('先到「描述符与状态」勾选描述符，再回来预填'); return; }
  const cov={};
  PALLC().forEach(p=>p.m.forEach(x=>{ if(!cov[x[0]]) cov[x[0]]=x; }));
  let n=0;
  Object.keys(sel.desc).forEach(nm=>{
    if(cov[nm]){ sel.desc[nm].src='政策库 · 依据「'+cov[nm][2]+'」；置信度 '+cov[nm][1]; n++; }
    else sel.desc[nm].src='（政策库中无对应路径，属外生输入或需另行设定）';
  });
  pulled=true;
  toast('已按政策库映射预填 '+n+' 个描述符的来源说明');
  render();
}

function uploadPolicy(){
  const inp=document.createElement('input');
  inp.type='file'; inp.accept='.csv,.txt';
  inp.onchange=e=>{
    const f=e.target.files[0]; if(!f) return;
    const r=new FileReader();
    r.onload=()=>{
      const lines=String(r.result).split(/\r?\n/).filter(x=>x.trim());
      const add=[];
      lines.forEach((ln,i)=>{
        if(i===0&&/路径|path|name/i.test(ln)&&!/[，,]/.test(ln.slice(0,12))) return;
        const p=ln.split(/[,\t]/).map(x=>x.trim());
        if(p[0]) add.push({c:p[0]||'自定义',g:p[1]||'自定义',n:p[2]||p[0],a:'自定义',s:p[3]||'',t:0,m:[]});
      });
      if(!add.length){ toast('没读到有效行，请用「类别,组别,路径,部门」的 CSV'); return; }
      polUser=polUser.concat(add);
      toast('已载入 '+add.length+' 条自定义政策路径');
      render();
    };
    r.readAsText(f,'utf-8');
  };
  inp.click();
}

function prepErr(ds, needScored){
  ds = ds || Object.keys(sel.desc);
  if(ds.length<2) return '至少选两个描述符';
  if(needScored===false) return null;
  return cimKeys().some(k=>cim[k]) ? null : '还没有打分，先到「交叉影响打分」做判断';
}
